{
  "ok": true,
  "summary": "Surface stage complete. Mapped the full DVWA v1.10 attack surface at http://127.0.0.1:8080. Found 30+ surfaces including authentication, all vulnerability modules, info disclosure (config backup with DB creds), file upload endpoint, directory listings, client-side JS files, and API-like source/help viewers. Database was created/reset successfully with admin/password credentials.",
  "surfaces": [
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/",
      "category": "root",
      "notes": "Redirects to login.php. Sets PHPSESSID cookie and security=low cookie."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/login.php",
      "category": "auth",
      "notes": "Authentication page. POST form with username, password, and user_token (CSRF anti-CSRF token). Default creds: admin/password."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/index.php",
      "category": "page",
      "notes": "Welcome/Home page after login. Shows username, security level, PHPIDS status."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/setup.php",
      "category": "admin",
      "notes": "Database setup/reset page. Also CSRF-protected POST form (user_token). After setup creates users table, guestbook table, config backup."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/security.php",
      "category": "admin",
      "notes": "Security level configuration (low/medium/high/impossible). Also PHPIDS enable/disable and IDS log viewer link. CSRF token included."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/instructions.php",
      "category": "page",
      "notes": "DVWA instructions and change log."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/about.php",
      "category": "page",
      "notes": "About page showing version 1.10 *Development* (Release date: 2015)."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/phpinfo.php",
      "category": "info_disclosure",
      "notes": "PHP info page exposing system details: Linux, Apache/2.4.25 (Debian), PHP 7.0.30-0+deb9u1, MySQL, etc."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/logout.php",
      "category": "auth",
      "notes": "Logout endpoint."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/ids_log.php",
      "category": "api",
      "notes": "PHPIDS log viewer. Shows previous attack simulation attempts. Can clear log via GET parameter."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/config/config.inc.php.bak",
      "category": "info_disclosure",
      "notes": "Config backup file exposed. Contains DB credentials: db_user=app, db_password=vulnerables, db_database=dvwa, db_server=127.0.0.1. Also reCAPTCHA keys (empty) and default security settings."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/brute/",
      "category": "vuln_module",
      "notes": "Brute Force module. GET form with username/password. SQL injection in query. MD5 password hashing."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/exec/",
      "category": "vuln_module",
      "notes": "Command Injection module. POST form with 'ip' parameter for ping command."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/csrf/",
      "category": "vuln_module",
      "notes": "CSRF module. GET form to change admin password (password_new, password_conf). No CSRF token."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/fi/",
      "category": "vuln_module",
      "notes": "File Inclusion module. GET parameter 'page' with file1.php/file2.php/file3.php. allow_url_include is Disabled."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/upload/",
      "category": "vuln_module",
      "notes": "File Upload module. Multipart/form-data POST. MAX_FILE_SIZE=100000. Uploads go to /hackable/uploads/."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/captcha/",
      "category": "vuln_module",
      "notes": "Insecure CAPTCHA module. POST form to change password with reCAPTCHA (missing API key). Hidden 'step' parameter."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/sqli/",
      "category": "vuln_module",
      "notes": "SQL Injection module. GET form with 'id' parameter."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/sqli_blind/",
      "category": "vuln_module",
      "notes": "SQL Injection (Blind) module. GET form with 'id' parameter."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/weak_id/",
      "category": "vuln_module",
      "notes": "Weak Session IDs module. POST button generates dvwaSession cookie."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/xss_d/",
      "category": "vuln_module",
      "notes": "XSS (DOM) module. GET parameter 'default' reflected in select option via client-side JS."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/xss_r/",
      "category": "vuln_module",
      "notes": "XSS (Reflected) module. GET form with 'name' parameter."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/xss_s/",
      "category": "vuln_module",
      "notes": "XSS (Stored) module. POST guestbook form with txtName and mtxMessage fields."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/csp/",
      "category": "vuln_module",
      "notes": "CSP Bypass module. POST form with 'include' parameter. CSP header: script-src 'self' https://pastebin.com example.com code.jquery.com https://ssl.google-analytics.com"
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/javascript/",
      "category": "vuln_module",
      "notes": "JavaScript Attacks module. POST form with phrase/token. Client-side uses MD5+ROT13 for token generation."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/view_source.php",
      "category": "api",
      "notes": "Source code viewer. Parameters: id (module name), security (low/medium/high/impossible). Shows PHP source of vulnerability modules."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/view_help.php",
      "category": "api",
      "notes": "Help popup viewer. Parameters: id (module name), security (level)."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/vulnerabilities/view_source_all.php",
      "category": "api",
      "notes": "Compare all security levels source. Parameter: id (module name)."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/hackable/uploads/",
      "category": "file",
      "notes": "Upload directory with directory listing enabled. Currently contains dvwa_email.png. Writable by www-data."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/config/",
      "category": "directory_listing",
      "notes": "Directory listing enabled. Contains config.inc.php (0 bytes, blocked) and config.inc.php.bak (accessible, 1859 bytes)."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/external/",
      "category": "directory_listing",
      "notes": "Directory listing enabled. External libraries directory."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/dvwa/js/dvwaPage.js",
      "category": "client",
      "notes": "Client-side JS: popUp function, form validation helpers, guestbook validation."
    },
    {
      "type": "url",
      "value": "http://127.0.0.1:8080/dvwa/js/add_event_listeners.js",
      "category": "client",
      "notes": "Client-side JS: adds click event listeners for View Source and Help buttons using dataset attributes."
    },
    {
      "type": "cookie",
      "value": "security",
      "category": "auth",
      "notes": "Security level cookie. Set to 'low' by default. Can be changed via security.php."
    },
    {
      "type": "cookie",
      "value": "PHPSESSID",
      "category": "auth",
      "notes": "PHP session cookie for authentication."
    }
  ],
  "candidates": [
    {
      "title": "Config Backup Exposes Database Credentials",
      "location": "http://127.0.0.1:8080/config/config.inc.php.bak",
      "proof_excerpt": "$_DVWA[ 'db_server' ]   = '127.0.0.1';\n$_DVWA[ 'db_database' ] = 'dvwa';\n$_DVWA[ 'db_user' ]     = 'app';\n$_DVWA[ 'db_password' ] = 'vulnerables';",
      "poc_hint": "Direct file access reveals MySQL credentials (app/vulnerables) for the dvwa database"
    },
    {
      "title": "Directory Listing Enabled on Multiple Paths",
      "location": "http://127.0.0.1:8080/config/",
      "proof_excerpt": "<title>Index of /config</title>...<a href=\"config.inc.php.bak\">config.inc.php.bak</a>...<a href=\"config.inc.php\">config.inc.php</a>",
      "poc_hint": "Apache directory listing on /config/ exposes config files"
    },
    {
      "title": "SQL Injection in Brute Force Module",
      "location": "http://127.0.0.1:8080/vulnerabilities/brute/",
      "proof_excerpt": "$query = \"SELECT * FROM `users` WHERE user = '$user' AND password = '$pass';\";",
      "poc_hint": "GET parameters username/password directly interpolated into SQL query without sanitization"
    },
    {
      "title": "Command Injection in Ping Module",
      "location": "http://127.0.0.1:8080/vulnerabilities/exec/",
      "proof_excerpt": "<form name=\"ping\" action=\"#\" method=\"post\"><p>Enter an IP address:<input type=\"text\" name=\"ip\" size=\"30\">",
      "poc_hint": "POST parameter 'ip' likely passed directly to shell ping command"
    },
    {
      "title": "CSRF Password Change Without Token",
      "location": "http://127.0.0.1:8080/vulnerabilities/csrf/",
      "proof_excerpt": "<form action=\"#\" method=\"GET\">New password:<br /><input type=\"password\" AUTOCOMPLETE=\"off\" name=\"password_new\"><br />Confirm new password:<br /><input type=\"password\" AUTOCOMPLETE=\"off\" name=\"password_conf\">",
      "poc_hint": "GET-based password change with no CSRF token - can be triggered via external page"
    },
    {
      "title": "Reflected XSS in XSS (DOM) Module",
      "location": "http://127.0.0.1:8080/vulnerabilities/xss_d/",
      "proof_excerpt": "var lang = document.location.href.substring(document.location.href.indexOf(\"default=\")+8);\ndocument.write(\"<option value='\" + lang + \"'>\" + decodeURI(lang) + \"</option>\");",
      "poc_hint": "URL parameter 'default' is directly written into DOM without sanitization"
    },
    {
      "title": "Reflected XSS in XSS (Reflected) Module",
      "location": "http://127.0.0.1:8080/vulnerabilities/xss_r/",
      "proof_excerpt": "<form name=\"XSS\" action=\"#\" method=\"GET\"><p>What's your name?<input type=\"text\" name=\"name\">",
      "poc_hint": "GET parameter 'name' reflected in page response"
    },
    {
      "title": "Stored XSS in Guestbook Module",
      "location": "http://127.0.0.1:8080/vulnerabilities/xss_s/",
      "proof_excerpt": "<input name=\"txtName\" type=\"text\" size=\"30\" maxlength=\"10\"><textarea name=\"mtxMessage\" cols=\"50\" rows=\"3\" maxlength=\"50\"></textarea>",
      "poc_hint": "Guestbook form stores txtName and mtxMessage which are displayed without sanitization"
    },
    {
      "title": "File Upload Vulnerability",
      "location": "http://127.0.0.1:8080/vulnerabilities/upload/",
      "proof_excerpt": "<form enctype=\"multipart/form-data\" action=\"#\" method=\"POST\"><input type=\"hidden\" name=\"MAX_FILE_SIZE\" value=\"100000\" /><input name=\"uploaded\" type=\"file\" />",
      "poc_hint": "Unrestricted file upload. Upload directory is writable and has directory listing: /hackable/uploads/"
    },
    {
      "title": "SQL Injection in SQL Injection Module",
      "location": "http://127.0.0.1:8080/vulnerabilities/sqli/",
      "proof_excerpt": "<form action=\"#\" method=\"GET\"><p>User ID:<input type=\"text\" size=\"15\" name=\"id\">",
      "poc_hint": "GET parameter 'id' passed directly to SQL query"
    },
    {
      "title": "File Inclusion via page Parameter",
      "location": "http://127.0.0.1:8080/vulnerabilities/fi/",
      "proof_excerpt": "[<em><a href=\"?page=file1.php\">file1.php</a></em>] - [<em><a href=\"?page=file2.php\">file2.php</a></em>] - [<em><a href=\"?page=file3.php\">file3.php</a></em>]",
      "poc_hint": "GET parameter 'page' controls file inclusion. Local file inclusion possible despite allow_url_include being disabled."
    },
    {
      "title": "Insecure CAPTCHA with Bypass via Step Parameter",
      "location": "http://127.0.0.1:8080/vulnerabilities/captcha/",
      "proof_excerpt": "<input type=\"hidden\" name=\"step\" value=\"1\" />\nNew password:<br />\n<input type=\"password\" AUTOCOMPLETE=\"off\" name=\"password_new\">",
      "poc_hint": "Hidden step parameter can be manipulated to bypass CAPTCHA verification"
    },
    {
      "title": "Weak Session ID Generation",
      "location": "http://127.0.0.1:8080/vulnerabilities/weak_id/",
      "proof_excerpt": "<form method=\"post\"><input type=\"submit\" value=\"Generate\" /></form>",
      "poc_hint": "Generates dvwaSession cookie on POST. May use predictable values."
    },
    {
      "title": "CSP Bypass via Allowed CDN Origins",
      "location": "http://127.0.0.1:8080/vulnerabilities/csp/",
      "proof_excerpt": "Content-Security-Policy: script-src 'self' https://pastebin.com  example.com code.jquery.com https://ssl.google-analytics.com ;",
      "poc_hint": "CSP allows scripts from pastebin.com, example.com, code.jquery.com, ssl.google-analytics.com - potential bypass vectors"
    },
    {
      "title": "Client-Side JavaScript Token Bypass",
      "location": "http://127.0.0.1:8080/vulnerabilities/javascript/",
      "proof_excerpt": "function generate_token() { var phrase = document.getElementById(\"phrase\").value; document.getElementById(\"token\").value = md5(rot13(phrase)); }",
      "poc_hint": "Token generation is client-side MD5(ROT13(phrase)). Can be computed offline to submit arbitrary values."
    }
  ],
